style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.imgur.com/TeowIQH.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Optional: Make Roblox page backgrounds transparent */
  .container-main,
  .rbx-body,
  .content,
  .section,
  .game-detail-page,
  #header,
  #navigation,
  #footer-container {
    background: transparent !important;
  }
}
